def main():
    for stem, d in DATA.items():
        (LESSONS / f"{stem}.md").write_text(render(stem, d), encoding="utf-8")
        marker, body = SVGS[stem]
        (MAPS / f"map-{stem[:2]}-{stem[3:]}.svg").write_text(svg(d["title"], d["alt"], marker, body), encoding="utf-8")
        print(stem)


if __name__ == "__main__":
    main()
